size, PyTypeObject *base_type)
{
VectorObject *self;
self = (VectorObject *) Vector_CreatePyObject_wrap(vec, size,
base_type);
if (self) {
self->flag &= ~BASE_MATH_FLAG_IS_WRAP;
}

